import{_ as i,o as a,c as s,a5 as t}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Server video editor deployment","description":"","frontmatter":{},"headers":[],"relativePath":"feature/server-video-editor/DEPLOYMENT.md","filePath":"feature/server-video-editor/DEPLOYMENT.md"}'),o={name:"feature/server-video-editor/DEPLOYMENT.md"};function r(n,e,d,l,p,c){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="server-video-editor-deployment" tabindex="-1">Server video editor deployment <a class="header-anchor" href="#server-video-editor-deployment" aria-label="Permalink to &quot;Server video editor deployment&quot;">​</a></h1><p>The worker is packaged in <code>brandhub-ai-service/Dockerfile.video-edit</code> and <code>compose.video-edit.yml</code>. It can run on a separate Linux VM; no VM has been deployed by this change. Business remains the authority for private media, ownership, quota and credits.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Copy <code>.env.video-edit.example</code> to ignored <code>.env.video-edit</code> in the AI repository. Set the existing internal service key, a Mongo URI/database, the Business origin, the existing Anthropic key/model, and the allowed upload capability origins. The worker does not need AWS credentials or <code>REPOSITORY_ENCRYPTION_KEY_V1</code>. Those stay in Business, which decrypts authorized sources and encrypts outputs.</p><p>For a worker on another VM, <code>VIDEO_EDIT_BUSINESS_URL</code> must be a reachable private Business origin. <code>VIDEO_EDIT_UPLOAD_ORIGINS</code> must match the gateway origin used in server-issued upload links. A localhost URL refers to the worker&#39;s own VM, so do not copy local URLs unchanged to a remote deployment.</p><p>Mount an existing faster-whisper model directory using <code>VIDEO_EDIT_HOST_MODEL_DIR</code>. Model files must include <code>model.bin</code>, configuration, tokenizer and vocabulary. Requests do not download models. Stock Edge TTS is optional and disabled by default; it needs outbound network access when enabled.</p><p>Configure the main AI service&#39;s <code>VIDEO_EDIT_RUNTIME_URL</code> to reach this worker. Keep port8094 on the private network and restrict ingress to the AI service; internal API calls still require the existing internal key.</p><h2 id="start-and-verify" tabindex="-1">Start and verify <a class="header-anchor" href="#start-and-verify" aria-label="Permalink to &quot;Start and verify&quot;">​</a></h2><p>From the AI repository:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.video-edit.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.video-edit.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.video-edit.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> video-edit</span></span></code></pre></div><p><code>GET /health</code> checks process readiness. The authenticated <code>GET /api/v1/ai/video-edit/capabilities</code> reports configured tools, model readiness and actual supported editing operations without making a provider call. Test the public Business submission/status/content flow before exposing it to users. An internal health response alone is not an end-to-end proof.</p><h2 id="capacity-and-recovery" tabindex="-1">Capacity and recovery <a class="header-anchor" href="#capacity-and-recovery" aria-label="Permalink to &quot;Capacity and recovery&quot;">​</a></h2><p>The compose package limits the worker to four CPUs,4GiB RAM,128 PIDs and a read-only root filesystem. It uses a writable scratch volume, one leased executor and a bounded durable queue. Benchmark real source material on the chosen VM before making turnaround promises. The600-second deadline is a limit, not a throughput guarantee.</p><p>Retain Mongo job records and output-session checkpoints during recovery. Completed outputs are separate private assets. Unknown Claude outcomes remain <code>RECONCILIATION_REQUIRED</code>; do not delete the job and silently retry a paid call. Output publication retries reuse the cached verified artifact and deterministic Business session. Archive or remove terminal scratch folders according to an operator retention policy; never remove an active job or its recovery files.</p><h2 id="capability-boundary" tabindex="-1">Capability boundary <a class="header-anchor" href="#capability-boundary" aria-label="Permalink to &quot;Capability boundary&quot;">​</a></h2><p>The executable pipeline probes media, samples frames, transcribes provided speech with a mounted model, plans with Claude, renders typed edits and checks the resulting MP4. It includes cuts, retiming, freeze/callouts, captions/titles, supplied alpha portraits, transitions and audio mixing. Unsupported manual effects fail explicitly. HyperFrames,Manim,CapCut and tracking/background-removal references are not advertised as executable server features.</p><p>Local evidence and limitations are recorded in the feature test report. No new footage generation, automatic publishing, cloud purchase or VM deployment is performed by starting this editor worker.</p>`,17)])])}const k=i(o,[["render",r]]);export{u as __pageData,k as default};
